#!/usr/bin/env perl
use strict;
use warnings;
use File::Find;

my $repo = '/bench/repo';
my $module = 'github.com/usememos/memos';

my %symbols;
my @go_files;

find(sub {
    return unless /\.go$/;
    push @go_files, $File::Find::name;
}, $repo);

for my $file (@go_files) {
    next unless $file =~ m{/internal/};
    open my $fh, '<', $file or die $!;
    my @lines = <$fh>;
    close $fh;

    my ($pkg) = grep { /^package\s+(\S+)/ } @lines;
    $pkg //= 'main';

    my $pkg_path = $file;
    $pkg_path =~ s/^\Q$repo\E\/internal\//internal\//;
    $pkg_path =~ s/\/[^\/]+\.go$//;

    for my $i (0 .. $#lines) {
        my $line = $lines[$i];
        next unless $line =~ /^func\s+/;
        my $recv = '';
        my $name;
        if ($line =~ /^func\s+\(([^)]*)\)\s+(\w+)\s*\(/) {
            $recv = normalize_recv($1);
            $name = $2;
        } elsif ($line =~ /^func\s+(\w+)\s*\(/) {
            $name = $1;
        } else {
            next;
        }
        next if $name eq 'init';

        my $key = symbol_key($pkg_path, $recv, $name);
        $symbols{$key} = {
            pkg_path => $pkg_path,
            pkg_name => $pkg,
            recv     => $recv,
            name     => $name,
            decl_file => $file,
            decl_line => $i + 1,
            sites    => {},
        };
    }
}

sub normalize_recv {
    my ($r) = @_;
    $r =~ s/^\*//;
    $r =~ s/^\s+|\s+$//g;
    $r =~ s/\s+\w+$//;
    return $r;
}

sub symbol_key {
    my ($pkg_path, $recv, $name) = @_;
    return $recv ? "$pkg_path|$recv|$name" : "$pkg_path||$name";
}

my %file_imports;
my %file_pkg;
my %file_is_internal;

for my $file (@go_files) {
    open my $fh, '<', $file or die $!;
    my $content = do { local $/; <$fh> };
    close $fh;

    ($file_pkg{$file}) = $content =~ /^package\s+(\S+)/m;
    $file_is_internal{$file} = ($file =~ m{/internal/}) ? 1 : 0;

    my %imports;
    while ($content =~ /^import\s+(?:\(\s*(.*?)\s*\)|"([^"]+)")/gms) {
        my $block = $1 // $2;
        if (defined $2) {
            my $path = $2;
            my $alias = (split '/', $path)[-1];
            $alias =~ s/;//;
            $imports{$alias} = $path;
        } else {
            while ($block =~ /(?:(\w+)\s+)?"([^"]+)"/g) {
                my ($alias, $path) = ($1, $2);
                $alias //= (split '/', $path)[-1];
                $alias =~ s/;//;
                $imports{$alias} = $path;
            }
        }
    }
    $file_imports{$file} = \%imports;
}

sub pkg_path_from_import {
    my ($import_path) = @_;
    return undef unless $import_path =~ s/^\Q$module\E\///;
    return $import_path;
}

sub add_site {
    my ($key, $file, $line) = @_;
    return unless exists $symbols{$key};
    my $s = $symbols{$key};
    if ($file eq $s->{decl_file} && $line == $s->{decl_line}) {
        return;
    }
    $s->{sites}{"$file:$line"} = 1;
}

my %go_keywords = map { $_ => 1 } qw(if for switch return func make new len cap append delete copy panic recover go defer map struct interface var const range select case default);

for my $file (@go_files) {
    open my $fh, '<', $file or die $!;
    my @lines = <$fh>;
    close $fh;

    my $imports = $file_imports{$file};
    my $in_internal = $file_is_internal{$file};

    my %alias_to_path;
    for my $alias (keys %$imports) {
        my $pp = pkg_path_from_import($imports->{$alias});
        next unless defined $pp && $pp =~ /^internal\//;
        $alias_to_path{$alias} = $pp;
    }

    my $local_pkg_path;
    if ($in_internal) {
        ($local_pkg_path) = ($file =~ m{/internal/(.+)\/[^/]+\.go$});
        $local_pkg_path = "internal/$local_pkg_path" if defined $local_pkg_path;
    }

    for my $i (0 .. $#lines) {
        my $line = $lines[$i];
        my $ln = $i + 1;
        next if $line =~ /^\s*\/\//;
        next if $line =~ /^\s*func\s+/;

        while ($line =~ /\b([A-Za-z_]\w*)\.([A-Za-z_]\w*)\s*\(/g) {
            my ($alias, $fname) = ($1, $2);
            if (exists $alias_to_path{$alias}) {
                my $pp = $alias_to_path{$alias};
                my $key = symbol_key($pp, '', $fname);
                add_site($key, $file, $ln) if exists $symbols{$key};
            }
        }

        while ($line =~ /\.([A-Za-z_]\w*)\s*\(/g) {
            my $mname = $1;
            for my $key (keys %symbols) {
                next unless $symbols{$key}{name} eq $mname;
                next unless $symbols{$key}{recv};
                add_site($key, $file, $ln);
            }
        }

        if ($in_internal && defined $local_pkg_path) {
            while ($line =~ /\b([A-Za-z_]\w*)\s*\(/g) {
                my $fname = $1;
                next if $go_keywords{$fname};
                my $key = symbol_key($local_pkg_path, '', $fname);
                add_site($key, $file, $ln) if exists $symbols{$key} && !$symbols{$key}{recv};
            }
        }
    }
}

my @ranked = sort {
    scalar(keys %{$b->{sites}}) <=> scalar(keys %{$a->{sites}})
        || $a->{name} cmp $b->{name}
} values %symbols;

print "TOTAL internal symbols: ", scalar(@ranked), "\n\n";
print "TOP 40:\n";
my $rank = 0;
for my $s (@ranked[0 .. 39]) {
    last unless $s;
    my $count = scalar keys %{$s->{sites}};
    next if $count == 0;
    $rank++;
    my $sym = $s->{recv} ? "$s->{recv}.$s->{name}" : $s->{name};
    my $decl = $s->{decl_file}; $decl =~ s/^\Q$repo\E\///;
    printf "%3d %4d  %s :: %s  (%s:%d)\n", $rank, $count, $s->{pkg_path}, $sym, $decl, $s->{decl_line};
}

PERL_EOF
perl /tmp/fanin_analysis.pl 2>&1 | head -60

