                my $key = symbol_key($pp, '', $fname);
                add_site($key, $file, $ln) if exists $symbols{$key};
            }
        }

        while ($line =~ /\.([A-Za-z_]\w*)\s*\(/g) {
            my $mname = $1;
            for my $key (keys %symbols) {
                next unless $symbols{$key}{name} eq $mname;
