                my $fname = $1;
                next if $go_keywords{$fname};
                my $key = symbol_key($local_pkg_path, '', $fname);
                add_site($key, $file, $ln) if exists $symbols{$key} && !$symbols{$key}{recv};
            }
        }
    }
}

my @ranked = sort {
    scalar(keys %{$b->{sites}}) <=> scalar(keys %{$a->{sites}})
        || $a->{name} cmp $b->{name}
} values %symbols;

