perl -e '
use strict; use warnings;
my $repo="/bench/repo"; my $module="github.com/usememos/memos";
open my $gf,"<","/tmp/go_files.txt" or die; chomp(my @go_files=<$gf>); close $gf;

sub pkg_path_from_file { my($f)=@_; return unless $f=~/\/internal\/(.+)\/[^\/]+\.go$/; "internal/$1"; }
sub sym_key { my($pp,$recv,$name)=@_; $recv?"$pp|$recv|$name":"$pp||$name"; }

my %symbols; my %pkg_funcs; my %methods; my %method_by_type; # type -> name -> key
for my $file (@go_files) {
  next unless $file=~/\/internal\//;
  my $pp=pkg_path_from_file($file) or next;
  open my $fh,"<",$file or die; my @lines=<$fh>; close $fh;
  for my $i (0..$#lines) {
    my $line=$lines[$i]; next unless $line=~/^func\s+/;
    my ($recv,$name)=("","");
    if ($line=~/^func\s+\(([^)]*)\)\s+(\w+)\s*\(/) {
      my $r=$1; $r=~s/^\*//; $r=~s/^\s+|\s+$//g; $r=~s/\s+\w+$//; $recv=$r; $name=$2;
    } elsif ($line=~/^func\s+(\w+)\s*\(/) { $name=$1; } else { next; }
    next if !defined $name || $name eq "" || $name eq "init";
    my $k=sym_key($pp,$recv,$name);
    $symbols{$k}={pp=>$pp,recv=>$recv,name=>$name,decl_file=>$file,decl_line=>$i+1,sites=>{}};
    if ($recv) { push @{$methods{$pp}{$name}}, $k; $method_by_type{"$pp|$recv"}{$name}=$k; }
    else { $pkg_funcs{$pp}{$name}=$k; }
  }
}

my %imports;
for my $file (@go_files) {
  open my $fh,"<",$file or die; my $c=do{local $/;<$fh>}; close $fh;
  my %imp;
  while ($c=~/^import\s+(?:\(\s*(.*?)\s*\)|"([^"]+)")/gms) {
    my $block=$1//$2;
    if (defined $2) { my $p=$2; my $a=(split"/",$p)[-1]; $a=~s/;//; $imp{$a}=$p; }
    else { while ($block=~/(?:(\w+)\s+)?"([^"]+)"/g) { my($a,$p)=($1,$2); $a//=(split"/",$p)[-1]; $a=~s/;//; $imp{$a}=$p; } }
  }
  $imports{$file}=\%imp;
}
sub internal_path { my $p=shift; return unless $p=~s/^\Q$module\E\///; $p if $p=~/^internal\//; }
sub add_site {
  my($k,$f,$l)=@_; return unless $symbols{$k};
  my $s=$symbols{$k};
  return if $f eq $s->{decl_file} && $l == $s->{decl_line};
  $s->{sites}{"$f:$l"}=1;
}
my %kw=map{$_=>1} qw(if for switch return func make new len cap append delete copy panic recover go defer map struct interface var const range select case default);

# constructor return types
my %ctor_ret;
for my $k (keys %symbols) {
  next if $symbols{$k}{recv}; my $fn=$symbols{$k}{name};
  next unless $fn=~/^New/ || $fn eq "New";
  open my $fh,"<",$symbols{$k}{decl_file} or next; my @L=<$fh>; close $fh;
  my $dl=$L[$symbols{$k}{decl_line}-1];
  if ($dl=~/\)\s+\*?(\w+)/) { $ctor_ret{$k}=$1; }
}

# per-file variable types and param types
my %vtype; # file|var -> "pp|Type"
for my $file (@go_files) {
  open my $fh,"<",$file or die; my $c=do{local $/;<$fh>}; close $fh;
  my $imp=$imports{$file}; my %a2p; for my $a (keys %$imp) { my $p=internal_path($imp->{$a}); $a2p{$a}=$p if $p; }
  # params in func signatures: func foo(engine *filter.Engine)
  while ($c=~/func\s+(?:\([^)]*\)\s+)?(\w+)\s*\(([^)]*)\)/g) {
    my $params=$2;
    while ($params=~/(\w+)\s+\*?([A-Za-z_]\w*)\.(\w+)/g) {
      my($v,$a,$t)=($1,$2,$3); next unless $a2p{$a}; $vtype{"$file|$v"}="$a2p{$a}|$t";
    }
    while ($params=~/(\w+)\s+\*?(\w+)/g) {
      my($v,$t)=($1,$2); next if $kw{$t}; # local type in same file packages - handled elsewhere
    }
  }
  for my $line (split /\n/, $c) {
    while ($line=~/(\w+)\s*:=\s*([A-Za-z_]\w*)\.(\w+)\s*\(/g) {
      my($v,$a,$fn)=($1,$2,$3); next unless $a2p{$a};
      my $ck=sym_key($a2p{$a},"",$fn); next unless $ctor_ret{$ck};
      $vtype{"$file|$v"}="$a2p{$a}|$ctor_ret{$ck}";
    }
    while ($line=~/(\w+)\s*,\s*[^:=]*:=\s*([A-Za-z_]\w*)\.(\w+)\s*\(/g) {
      my($v,$a,$fn)=($1,$2,$3); next unless $a2p{$a};
      my $ck=sym_key($a2p{$a},"",$fn); next unless $ctor_ret{$ck};
      $vtype{"$file|$v"}="$a2p{$a}|$ctor_ret{$ck}";
    }
    while ($line=~/var\s+(\w+)\s+\*?([A-Za-z_]\w*)\.(\w+)/g) {
      my($v,$a,$t)=($1,$2,$3); next unless $a2p{$a}; $vtype{"$file|$v"}="$a2p{$a}|$t";
    }
  }
}

# same-package unqualified type vars: engine *Engine in filter package
for my $file (@go_files) {
  my $pp=pkg_path_from_file($file); next unless $pp;
  open my $fh,"<",$file or die; my $c=do{local $/;<$fh>}; close $fh;
  while ($c=~/(\w+)\s+\*?(\w+)/g) {
    my($v,$t)=($1,$2); next if $kw{$v}||$kw{$t};
    if ($method_by_type{"$pp|$t"}) { $vtype{"$file|$v"}="$pp|$t" unless exists $vtype{"$file|$v"}; }
  }
}

sub resolve_method {
  my($file,$recv,$method)=@_;
  my @keys;
  if (my $tt=$vtype{"$file|$recv"}) { return $method_by_type{$tt}{$method}; }
  my $pp=pkg_path_from_file($file);
  if ($pp && $method_by_type{"$pp|$recv"}) { return $method_by_type{"$pp|$recv"}{$method}; }
  if ($pp && @{$methods{$pp}{$method}//[]}) {
    return $methods{$pp}{$method}[0] if @{$methods{$pp}{$method}}==1;
  }
  return undef;
}

for my $file (@go_files) {
  open my $fh,"<",$file or die; my @lines=<$fh>; close $fh;
  my $imp=$imports{$file}; my %a2p; for my $a (keys %$imp) { my $p=internal_path($imp->{$a}); $a2p{$a}=$p if $p; }
  my $lpp=pkg_path_from_file($file);
  for my $i (0..$#lines) {
    my ($line,$ln)=($lines[$i],$i+1);
    next if $line=~/^\s*\/\// || $line=~/^\s*func\s+/;
    # package qualified func calls
    while ($line=~/\b([A-Za-z_]\w*)\.([A-Za-z_]\w*)\s*\(/g) {
      my($a,$fn)=($1,$2); next unless $a2p{$a};
      my $k=sym_key($a2p{$a},"",$fn); add_site($k,$file,$ln) if $symbols{$k};
    }
    # unqualified package funcs in same internal package
    if ($lpp) {
      while ($line=~/\b([A-Za-z_]\w*)\s*\(/g) {
        my $fn=$1; next if $kw{$fn}; next unless $pkg_funcs{$lpp}{$fn};
        add_site($pkg_funcs{$lpp}{$fn},$file,$ln);
      }
    }
    # method calls recv.method(
    while ($line=~/(\w+)\.(\w+)\s*\(/g) {
      my($rv,$mn)=($1,$2); next if $kw{$rv};
      my $k=resolve_method($file,$rv,$mn); add_site($k,$file,$ln) if $k;
    }
  }
}

my @ranked=sort{scalar(keys%{$b->{sites}})<=>scalar(keys%{$a->{sites}}) || $a->{name} cmp $b->{name}} values %symbols;
print "FINAL TOP 25:\n"; my $n=0;
for my $s (@ranked) { my $c=scalar keys %{$s->{sites}}; next unless $c>0; $n++; last if $n>25;
  my $sym=$s->{recv}?"$s->{recv}.$s->{name}":$s->{name}; my $d=$s->{decl_file}; $d=~s/^\Q$repo\E\///;
  printf "%3d %4d  %s :: %s  (%s:%d)\n",$n,$c,$s->{pp},$sym,$d,$s->{decl_line};
}
# detail top
my $top=$ranked[0]; while($top && !scalar(keys%{$top->{sites}})) { shift @ranked; $top=$ranked[0]; }
if ($top) {
  print "\nTOP SITES (first 20):\n"; my $i=0;
  for my $site (sort keys %{$top->{sites}}) { $site=~s/^\Q$repo\E\///; print "  $site\n"; last if ++$i>=20; }
}
' 2>/dev/null

