args.command:
perl -e '
use strict; use warnings;
my $repo="/bench/repo"; my $module="github.com/usememos/memos";
open my $gf,"<","/tmp/go_files.txt" or die; chomp(my @go_files=<$gf>); close $gf;
my (%decls,%name_count);
for my $file (@go_files) {
  open my $fh,"<",$file or die; my @lines=<$fh>; close $fh;
  for my $i (0..$#lines) {
    my $line=$lines[$i]; next unless $line=~/^func\s+/;
    my $name;
    if ($line=~/^func\s+\([^)]*\)\s+(\w+)\s*\(/) { $name=$1; }
    elsif ($line=~/^func\s+(\w+)\s*\(/) { $name=$1; } else { next; }
    next if $name eq "init";
    $name_count{$name}++;
    push @{$decls{$name}}, [$file,$i+1,$line] if $file=~/\/internal\//;
  }
}
# For each internal decl with unique name repo-wide, count
my @rows;
for my $name (keys %decls) {
  next unless $name_count{$name}==1;
  my ($file,$line)=@{$decls{$name}[0]};
  my %sites;
  for my $f (@go_files) {
    open my $fh,"<",$f or die; my @L=<$fh>; close $fh;
    for my $i (0..$#L) {
      my $ln=$i+1; next if $f eq $file && $ln==$line;
      next unless $L[$i]=~/\b\Q$name\E\s*\(/;
      $sites{"$f:$ln"}=1;
    }
  }
  my $pp=$file; $pp=~s/^\Q$repo\E\/internal\//internal\//; $pp=~s/\/[^\/]+$//;
  my $recv=""; if ($decls{$name}[0][2]=~/^func\s+\(([^)]*)\)/) { my $r=$1; $r=~s/^\*//; $r=~s/\s+\w+$//; $recv=$r; }
  my $sym=$recv?"$recv.$name":$name;
  push @rows, [scalar(keys%sites),$pp,$sym,"$file:$line"];
}
@rows=sort{$b->[0]<=>$a->[0]}@rows;
print "Top 15 unique-name internal symbols:\n";
for my $i (0..14) { printf "%2d. %3d  %s :: %s  (%s)\n",$i+1,$rows[$i][0],$rows[$i][1],$rows[$i][2],$rows[$i][3]; $rows[$i][3]=~s/^\Q$repo\E\///; }
' 2>/dev/null

