use strict; use warnings;
my $repo="/bench/repo";
open my $gf,"<","/tmp/go_files.txt" or die; chomp(my @go_files=<$gf>); close $gf;

my (%internal,%global_key);
for my $file (@go_files) {
  open my $fh,"<",$file or die; my @lines=<$fh>; close $fh;
  for my $i (0..$#lines) {
    my $line=$lines[$i]; next unless $line=~/^func\s+/;
    my ($recv,$name)=("","");
    if ($line=~/^func\s+\(([^)]*)\)\s+(\w+)\s*\(/) {
      my $r=$1; $r=~s/^\*//; $r=~s/^\s+|\s+$//g; $r=~s/\s+\w+$//; $recv=$r; $name=$2;
    } elsif ($line=~/^func\s+(\w+)\s*\(/) { $name=$1; } else { next; }
    next if $name eq "init";
    my $gkey = $recv ? "$recv|$name" : "|$name";
    $global_key{$gkey}++;
    next unless $file=~/\/internal\//;
    my $pp=$file; $pp=~s/^\Q$repo\E\/internal\//internal\//; $pp=~s/\/[^\/]+$//;
    push @{$internal{$gkey}}, {pp=>$pp,recv=>$recv,name=>$name,file=>$file,line=>$i+1};
  }
}

my @rows;
for my $gkey (keys %internal) {
  next unless $global_key{$gkey}==1; # unique receiver+name in whole repo
  my $d=$internal{$gkey}[0]; my ($file,$line,$name)=@{$d}{qw/file line name/};
  my %sites;
  for my $f (@go_files) {
    open my $fh,"<",$f or die; my @L=<$fh>; close $fh;
    for my $i (0..$#L) {
      my $ln=$i+1; next if $f eq $file && $ln==$line;
      my $l=$L[$i];
      if ($d->{recv}) {
        next unless $l=~/\.\Q$name\E\s*\(/;
      } else {
        next unless $l=~/\b\Q$name\E\s*\(/;
      }
      $sites{"$f:$ln"}=1;
    }
  }
  my $sym=$d->{recv}?"$d->{recv}.$name":$name;
  push @rows, [scalar(keys%sites),$d->{pp},$sym,$file,$line];
}
@rows=sort{$b->[0]<=>$a->[0]}@rows;
print "Top 20 internal symbols unique by (receiver,name) across repo:\n";
for my $i (0..19) {
  my $r=$rows[$i]; my $path=$r->[3]; $path=~s/^\Q$repo\E\///;
  printf "%2d. %3d  %s :: %s  (%s:%d)\n",$i+1,$r->[0],$r->[1],$r->[2],$path,$r->[4];
}
' 2>/dev/null

